/** 判题脚手架：外部状态源与调度器的类型契约（测试与考生共用）。 */
export interface MetricState {
  readonly version: number;
  readonly latest: number;
  readonly total: number;
}

export interface MetricStore {
  subscribe(listener: () => void): () => void;
  push(value: number): void;
  getSnapshot(): MetricState;
}

/** 注入的"下一帧"调度：返回取消函数。判题环境禁墙钟，所以窗口推进由测试握住。 */
export type Scheduler = (task: () => void) => () => void;

import { act, render, screen } from '@testing-library/react';
import { Profiler } from 'react';
import { afterEach, expect, it, vi } from 'vitest';
import type { Scheduler } from './storeKit';
import { MetricPanel, createMetricStore, useMetricWindow } from './Solution';

function makeScheduler() {
  const live = new Set<{ run: () => void }>();
  let cancels = 0;
  const schedule: Scheduler = (task) => {
    const box = { run: task };
    live.add(box);
    return () => {
      cancels += 1;
      live.delete(box);
    };
  };
  const flush = () => {
    const items = [...live];
    live.clear();
    items.forEach((box) => box.run());
  };
  return { schedule, flush, pending: () => live.size, cancels: () => cancels };
}

/** 帧探针：Profiler 在 commit 之后回调，此时读 DOM 就是这一帧真正提交的内容。 */
function mountPanel() {
  const commits: string[] = [];
  const store = createMetricStore();
  const s = makeScheduler();
  function frame() {
    return screen.getByTestId('latest').textContent + '/' + screen.getByTestId('total').textContent;
  }
  const view = render(
    <Profiler id="panel" onRender={() => commits.push(frame())}>
      <MetricPanel store={store} schedule={s.schedule} />
    </Profiler>,
  );
  const pushMany = (count: number, from = 1) => {
    act(() => {
      for (let i = 0; i < count; i += 1) store.push(from + i);
    });
  };
  const flush = () => {
    act(() => s.flush());
  };
  return { store, s, commits, frame, pushMany, flush, unmount: view.unmount };
}

afterEach(() => {
  vi.restoreAllMocks();
});

it('同一版本连续读取快照引用稳定且旧快照不被就地改写', () => {
  const store = createMetricStore();
  const before = store.getSnapshot();
  expect(store.getSnapshot()).toBe(before);
  expect(before.version).toBe(0);
  expect(before.latest).toBe(0);
  store.push(5);
  const after = store.getSnapshot();
  expect(after).not.toBe(before);
  expect(after.version).toBe(1);
  expect(after.latest).toBe(5);
  expect(before.latest).toBe(0);
  expect(store.getSnapshot()).toBe(after);
});

it('无数据推送时不调度也不额外提交', () => {
  const m = mountPanel();
  expect(m.s.pending()).toBe(0);
  expect(m.commits.length).toBe(1);
  expect(m.frame()).toBe('0/0');
});

it('窗口内重复 push 合并为一次提交并保留末值', () => {
  const m = mountPanel();
  m.pushMany(5);
  expect(m.s.pending()).toBe(1);
  expect(m.commits.length).toBe(1);
  expect(m.frame()).toBe('0/0');
  m.flush();
  expect(m.commits.length).toBe(2);
  expect(m.frame()).toBe('5/5');
});

it('超大 1000 次 push 只排一个任务且一帧收敛', () => {
  const m = mountPanel();
  m.pushMany(1000);
  expect(m.s.pending()).toBe(1);
  m.flush();
  expect(m.commits.length).toBe(2);
  expect(m.frame()).toBe('1000/1000');
});

it('卸载后取消调度任务且晚到任务不再提交', () => {
  const noise: string[] = [];
  vi.spyOn(console, 'error').mockImplementation((...args: unknown[]) => noise.push(args.map(String).join(' ')));
  const m = mountPanel();
  m.pushMany(3);
  expect(m.s.pending()).toBe(1);
  const before = m.commits.length;
  m.unmount();
  expect(m.s.cancels()).toBe(1);
  m.flush();
  expect(m.commits.length).toBe(before);
  expect(noise).toEqual([]);
});

it('订阅者退订后不再被通知', () => {
  const store = createMetricStore();
  let hits1 = 0;
  let hits2 = 0;
  const off1 = store.subscribe(() => { hits1 += 1; });
  store.subscribe(() => { hits2 += 1; });
  store.push(1);
  expect(hits1).toBe(1);
  expect(hits2).toBe(1);
  off1();
  store.push(2);
  expect(hits1).toBe(1);
  expect(hits2).toBe(2);
  expect(store.getSnapshot().total).toBe(2);
});

