import { useCallback, useSyncExternalStore } from 'react';
import type { MetricState, MetricStore, Scheduler } from './storeKit';

/**
 * 不可变快照：同一 version 永远返回同一个对象引用。
 * getSnapshot 每次新建对象 = useSyncExternalStore 判定"变了" → 无限重渲染。
 */
export function createMetricStore(): MetricStore {
  let snapshot: MetricState = { version: 0, latest: 0, total: 0 };
  const listeners = new Set<() => void>();
  return {
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    push(value: number) {
      snapshot = { version: snapshot.version + 1, latest: value, total: snapshot.total + 1 };
      listeners.forEach((listener) => listener());
    },
    getSnapshot() {
      return snapshot;
    },
  };
}

/**
 * 高频 store（16ms 一个点）直连组件会把主线程排满：
 * 这里把"通知 React"这件事按窗口合并——同一次 flush 内无论 push 多少次都只调度一个任务，
 * 且任务执行时读的是当时的最新快照（尾帧保留，不会把末尾的点丢掉）。
 */
export function useMetricWindow(store: MetricStore, schedule: Scheduler): MetricState {
  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      let scheduled = false;
      let cancel: (() => void) | null = null;
      const unsubscribe = store.subscribe(() => {
        if (scheduled) return;
        scheduled = true;
        cancel = schedule(() => {
          scheduled = false;
          cancel = null;
          onStoreChange();
        });
      });
      return () => {
        unsubscribe();
        if (cancel) cancel();
      };
    },
    [store, schedule],
  );
  const getSnapshot = useCallback(() => store.getSnapshot(), [store]);
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

export function MetricPanel({ store, schedule }: { store: MetricStore; schedule: Scheduler }) {
  const state = useMetricWindow(store, schedule);
  return (
    <div>
      <span data-testid="latest">{state.latest}</span>
      <span data-testid="version">{state.version}</span>
      <span data-testid="total">{state.total}</span>
    </div>
  );
}

