import { useSyncExternalStore } from 'react';

const state = { version: 0, latest: 0, total: 0 };
const listeners = new Set<() => void>();

export function createMetricStore() {
  return {
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    push(value: number) {
      // 就地改写同一个对象：引用永远不变，React 看不出变化
      state.latest = value;
      state.total += 1;
      state.version += 1;
      listeners.forEach((listener) => listener());
    },
    getSnapshot: () => state,
  };
}

export function useMetricWindow(store, schedule) {
  void schedule;
  return useSyncExternalStore(store.subscribe, store.getSnapshot);
}

export function MetricPanel({ store, schedule }) {
  const s = useMetricWindow(store, schedule);
  return (
    <div>
      <span data-testid="latest">{s.latest}</span>
      <span data-testid="version">{s.version}</span>
      <span data-testid="total">{s.total}</span>
    </div>
  );
}
